/**
 * Phase 3.2: Backend Service Consolidation - Auditable Service Class
 *
 * Extends BaseService with comprehensive audit logging capabilities.
 * Provides consistent patterns for tracking user actions, account changes,
 * and resource modifications across all services.
 *
 * Features:
 * - User action logging (login, logout, profile changes)
 * - Account action logging (subscription, billing, settings)
 * - Resource action logging (CRUD operations)
 * - Compliance-ready audit trails
 * - Integration with audit log system
 */

import { BaseService, type ServiceContext } from "./BaseService";
import { prisma } from "@infra/prisma";
import { logger } from "../lib/logger.js";

// Audit action types (matching database schema - uses strings, not enums)
export type AuditAction = string;
export type AuditCategory =
  | "AUTHENTICATION"
  | "ACCOUNT"
  | "DATA"
  | "DATA_ACCESS"
  | "SECURITY"
  | "COMPLIANCE"
  | "SYSTEM"
  | "BILLING";
export type AuditSeverity = "LOW" | "INFO" | "MEDIUM" | "HIGH" | "CRITICAL";

export interface AuditLogEntry {
  action: AuditAction;
  category: AuditCategory;
  severity: AuditSeverity;
  userId?: string;
  accountId?: string;
  resourceType?: string;
  resourceId?: string;
  details?: Record<string, unknown>;
  ipAddress?: string;
  userAgent?: string;
  metadata?: Record<string, unknown>;
}

export interface UserActionOptions {
  action: AuditAction;
  category: AuditCategory;
  severity?: AuditSeverity;
  details?: Record<string, unknown>;
  ipAddress?: string;
  userAgent?: string;
}

export interface AccountActionOptions extends UserActionOptions {
  accountId: string;
}

export interface ResourceActionOptions extends AccountActionOptions {
  resourceType: string;
  resourceId: string;
}

/**
 * Auditable Service - Base class for services requiring audit logging
 * Extends BaseService with audit trail capabilities
 */
export abstract class AuditableService extends BaseService {
  /**
   * Log a user action (authentication, profile changes, etc.)
   *
   * @example
   * await this.logUserAction(userId, {
   *   action: 'USER_LOGIN',
   *   category: 'AUTHENTICATION',
   *   severity: 'INFO',
   *   details: { method: 'password' },
   *   ipAddress: req.ip,
   *   userAgent: req.headers['user-agent']
   * });
   */
  protected async logUserAction(userId: string, options: UserActionOptions): Promise<void> {
    const entry: AuditLogEntry = {
      action: options.action,
      category: options.category,
      severity: options.severity || "INFO",
      userId,
      ...(options.details !== undefined && { details: options.details }),
      ...(options.ipAddress !== undefined && { ipAddress: options.ipAddress }),
      ...(options.userAgent !== undefined && { userAgent: options.userAgent }),
    };

    await this.writeAuditLog(entry);
  }

  /**
   * Log an account-level action (subscription, billing, settings)
   *
   * @example
   * await this.logAccountAction(userId, {
   *   accountId: account.id,
   *   action: 'SUBSCRIPTION_UPGRADE',
   *   category: 'BILLING',
   *   severity: 'HIGH',
   *   details: {
   *     from: 'FREE',
   *     to: 'PRO',
   *     billingCycle: 'MONTHLY'
   *   }
   * });
   */
  protected async logAccountAction(userId: string, options: AccountActionOptions): Promise<void> {
    const entry: AuditLogEntry = {
      action: options.action,
      category: options.category,
      severity: options.severity || "MEDIUM",
      userId,
      accountId: options.accountId,
      ...(options.details !== undefined && { details: options.details }),
      ...(options.ipAddress !== undefined && { ipAddress: options.ipAddress }),
      ...(options.userAgent !== undefined && { userAgent: options.userAgent }),
    };

    await this.writeAuditLog(entry);
  }

  /**
   * Log a resource action (create, update, delete operations)
   *
   * @example
   * await this.logResourceAction(userId, {
   *   accountId: account.id,
   *   action: 'RESOURCE_CREATE',
   *   category: 'DATA',
   *   resourceType: 'Post',
   *   resourceId: post.id,
   *   severity: 'LOW',
   *   details: {
   *     title: post.title,
   *     status: post.status
   *   }
   * });
   */
  protected async logResourceAction(userId: string, options: ResourceActionOptions): Promise<void> {
    const entry: AuditLogEntry = {
      action: options.action,
      category: options.category,
      severity: options.severity || "LOW",
      userId,
      accountId: options.accountId,
      resourceType: options.resourceType,
      resourceId: options.resourceId,
      ...(options.details !== undefined && { details: options.details }),
      ...(options.ipAddress !== undefined && { ipAddress: options.ipAddress }),
      ...(options.userAgent !== undefined && { userAgent: options.userAgent }),
    };

    await this.writeAuditLog(entry);
  }

  /**
   * Log security-related events (MFA, password changes, permission changes)
   *
   * @example
   * await this.logSecurityEvent(userId, accountId, {
   *   action: 'MFA_ENABLED',
   *   category: 'SECURITY',
   *   severity: 'HIGH',
   *   details: { method: 'totp' }
   * });
   */
  protected async logSecurityEvent(
    userId: string,
    accountId: string,
    options: Omit<UserActionOptions, "category">
  ): Promise<void> {
    await this.logAccountAction(userId, {
      accountId,
      category: "SECURITY",
      ...options,
    });
  }

  /**
   * Log data access events (for compliance and privacy)
   *
   * @example
   * await this.logDataAccess(userId, accountId, {
   *   action: 'DATA_EXPORT',
   *   resourceType: 'Analytics',
   *   resourceId: project.id,
   *   details: { format: 'CSV', recordCount: 1000 }
   * });
   */
  protected async logDataAccess(
    userId: string,
    accountId: string,
    options: Omit<ResourceActionOptions, "category" | "accountId">
  ): Promise<void> {
    await this.logResourceAction(userId, {
      accountId,
      category: "DATA_ACCESS",
      severity: "MEDIUM",
      ...options,
    });
  }

  /**
   * Log compliance-related events (GDPR, data deletion, consent)
   *
   * @example
   * await this.logComplianceEvent(userId, accountId, {
   *   action: 'DATA_DELETION_REQUEST',
   *   severity: 'CRITICAL',
   *   details: { scope: 'all_personal_data' }
   * });
   */
  protected async logComplianceEvent(
    userId: string,
    accountId: string,
    options: Omit<AccountActionOptions, "category" | "accountId">
  ): Promise<void> {
    await this.logAccountAction(userId, {
      accountId,
      category: "COMPLIANCE",
      severity: "CRITICAL",
      ...options,
    });
  }

  /**
   * Write audit log entry to database
   * Can be overridden for custom audit log storage
   *
   * Note: Maps AuditableService structure to Prisma AuditLog schema
   * - action: stored as-is
   * - resourceType: stored as 'resource' field
   * - category/severity: stored in details for queryability
   */
  protected async writeAuditLog(entry: AuditLogEntry): Promise<void> {
    try {
      // Merge category/severity into details for storage
      const enrichedDetails = {
        ...(entry.details || {}),
        category: entry.category,
        severity: entry.severity,
        ...(entry.metadata || {}),
      };

      await prisma.auditLog.create({
        data: {
          action: entry.action,
          ...(entry.resourceType && { resource: entry.resourceType }),
          ...(entry.resourceId && { resourceId: entry.resourceId }),
          ...(entry.userId && { userId: entry.userId }),
          ...(entry.ipAddress && { ipAddress: entry.ipAddress }),
          ...(entry.userAgent && { userAgent: entry.userAgent }),
          details: enrichedDetails,
          success: true, // Default to success for normal audit logs
        },
      });
    } catch (error) {
      // Log audit logging failure (don't throw to avoid breaking main operation)
      logger.error(
        {
          err: error instanceof Error ? error : new Error(String(error)),
          entry,
        },
        "Failed to write audit log"
      );
    }
  }

  /**
   * Execute operation with automatic audit logging
   * Logs both success and failure
   *
   * @example
   * return this.executeWithAudit(
   *   { operation: 'updateUser', userId, accountId },
   *   {
   *     action: 'USER_UPDATE',
   *     category: 'ACCOUNT',
   *     resourceType: 'User',
   *     resourceId: userId
   *   },
   *   async () => {
   *     const updated = await prisma.user.update({ ... });
   *     return updated;
   *   }
   * );
   */
  protected async executeWithAudit<T>(
    context: Omit<ServiceContext, "serviceName">,
    auditOptions: {
      action: AuditAction;
      category: AuditCategory;
      resourceType?: string;
      resourceId?: string;
      severity?: AuditSeverity;
      ipAddress?: string;
      userAgent?: string;
    },
    operation: () => Promise<T>
  ): Promise<T> {
    const startTime = Date.now();
    let error: unknown;

    try {
      const result = await operation();
      // Log successful operation
      if (context.userId) {
        const entry: AuditLogEntry = {
          action: auditOptions.action,
          category: auditOptions.category,
          severity: auditOptions.severity || "LOW",
          userId: context.userId,
          ...(context.accountId !== undefined && { accountId: context.accountId }),
          ...(auditOptions.resourceType !== undefined && {
            resourceType: auditOptions.resourceType,
          }),
          ...(auditOptions.resourceId !== undefined && { resourceId: auditOptions.resourceId }),
          ...(auditOptions.ipAddress !== undefined && { ipAddress: auditOptions.ipAddress }),
          ...(auditOptions.userAgent !== undefined && { userAgent: auditOptions.userAgent }),
          details: {
            operation: context.operation,
            durationMs: Date.now() - startTime,
            success: true,
          },
        };
        await this.writeAuditLog(entry);
      }

      return result;
    } catch (err) {
      error = err;

      // Log failed operation
      if (context.userId) {
        const entry: AuditLogEntry = {
          action: auditOptions.action,
          category: auditOptions.category,
          severity: "HIGH", // Failed operations are high severity
          userId: context.userId,
          ...(context.accountId !== undefined && { accountId: context.accountId }),
          ...(auditOptions.resourceType !== undefined && {
            resourceType: auditOptions.resourceType,
          }),
          ...(auditOptions.resourceId !== undefined && { resourceId: auditOptions.resourceId }),
          ...(auditOptions.ipAddress !== undefined && { ipAddress: auditOptions.ipAddress }),
          ...(auditOptions.userAgent !== undefined && { userAgent: auditOptions.userAgent }),
          details: {
            operation: context.operation,
            durationMs: Date.now() - startTime,
            success: false,
            error: error instanceof Error ? error.message : String(error),
          },
        };
        await this.writeAuditLog(entry);
      }

      throw err;
    }
  }

  /**
   * Query audit logs for a user
   * Note: category is stored in details field, not as a direct column
   */
  protected async getUserAuditLogs(
    userId: string,
    options?: {
      limit?: number;
      offset?: number;
      action?: string;
      startDate?: Date;
      endDate?: Date;
    }
  ) {
    return prisma.auditLog.findMany({
      where: {
        userId,
        ...(options?.action && { action: options.action }),
        ...(options?.startDate &&
          options?.endDate && {
            createdAt: {
              gte: options.startDate,
              lte: options.endDate,
            },
          }),
      },
      orderBy: { createdAt: "desc" },
      take: options?.limit || 50,
      skip: options?.offset || 0,
    });
  }

  /**
   * Query audit logs for a resource
   * Note: Since accountId is not in schema, query by resource/resourceId
   */
  protected async getResourceAuditLogs(
    resource: string,
    resourceId: string,
    options?: {
      limit?: number;
      offset?: number;
      action?: string;
      startDate?: Date;
      endDate?: Date;
    }
  ) {
    return prisma.auditLog.findMany({
      where: {
        resource,
        resourceId,
        ...(options?.action && { action: options.action }),
        ...(options?.startDate &&
          options?.endDate && {
            createdAt: {
              gte: options.startDate,
              lte: options.endDate,
            },
          }),
      },
      orderBy: { createdAt: "desc" },
      take: options?.limit || 50,
      skip: options?.offset || 0,
    });
  }
}

src/services/BaseService.ts.source:
/**
 * Phase 3.1: Backend Service Consolidation - Base Service Class
 *
 * Provides consistent error handling, logging, and validation patterns
 * across all backend services to eliminate duplication.
 *
 * Features:
 * - Standardized error handling with Result<T, E> pattern
 * - Contextual logging with structured data
 * - Input validation helpers
 * - Performance timing
 * - Consistent error responses
 */

import { Result, ok, err } from "@shared/types";
import { logger } from "../lib/logger.js";

export interface ServiceContext {
  serviceName: string;
  operation: string;
  userId?: string;
  accountId?: string;
  metadata?: Record<string, unknown>;
}

export interface ServiceError {
  code: string;
  message: string;
  details?: Record<string, unknown>;
  timestamp: Date;
  context: ServiceContext;
}

/**
 * Base class for all backend services
 * Provides consistent error handling, logging, and validation
 */
export abstract class BaseService {
  protected serviceName: string;

  constructor(serviceName: string) {
    this.serviceName = serviceName;
  }

  /**
   * Execute an operation with standardized error handling
   *
   * @example
   * return this.executeWithErrorHandling(
   *   { operation: 'createUser', userId: '123' },
   *   async () => {
   *     const user = await prisma.user.create({ data });
   *     return user;
   *   }
   * );
   */
  protected async executeWithErrorHandling<T>(
    context: Omit<ServiceContext, "serviceName">,
    operation: () => Promise<T>
  ): Promise<Result<T, string>> {
    const fullContext: ServiceContext = {
      serviceName: this.serviceName,
      ...context,
    };

    const startTime = Date.now();

    try {
      const result = await operation();
      const duration = Date.now() - startTime;

      this.logOperation(fullContext, "success", duration);

      return ok(result);
    } catch (error) {
      const duration = Date.now() - startTime;

      const serviceError = this.createServiceError(error, fullContext);
      this.logError(fullContext, serviceError, duration);

      return err(serviceError.message);
    }
  }

  /**
   * Execute an operation with error handling and return raw result (throws on error)
   * Use this when you want to handle errors in the calling code
   */
  protected async execute<T>(
    context: Omit<ServiceContext, "serviceName">,
    operation: () => Promise<T>
  ): Promise<T> {
    const fullContext: ServiceContext = {
      serviceName: this.serviceName,
      ...context,
    };

    const startTime = Date.now();

    try {
      const result = await operation();
      const duration = Date.now() - startTime;

      this.logOperation(fullContext, "success", duration);

      return result;
    } catch (error) {
      const duration = Date.now() - startTime;
      const serviceError = this.createServiceError(error, fullContext);

      this.logError(fullContext, serviceError, duration);

      throw error;
    }
  }

  /**
   * Validate that all required values are present and non-null
   * Throws error if any value is null/undefined
   *
   * @example
   * this.validateRequired(
   *   { userId, accountId },
   *   'Missing required fields'
   * );
   */
  protected validateRequired(
    values: Record<string, unknown>,
    errorMessage = "Missing required fields"
  ): void {
    const missingFields: string[] = [];

    for (const [key, value] of Object.entries(values)) {
      if (value === null || value === undefined || value === "") {
        missingFields.push(key);
      }
    }

    if (missingFields.length > 0) {
      throw new Error(`${errorMessage}: ${missingFields.join(", ")}`);
    }
  }

  /**
   * Validate that at least one of the provided values is present
   */
  protected validateAtLeastOne(
    values: Record<string, unknown>,
    errorMessage = "At least one field is required"
  ): void {
    const hasValue = Object.values(values).some((value) => value !== null && value !== undefined);

    if (!hasValue) {
      throw new Error(`${errorMessage}: ${Object.keys(values).join(", ")}`);
    }
  }

  /**
   * Create a standardized service error
   */
  protected createServiceError(error: unknown, context: ServiceContext): ServiceError {
    const errorMessage = error instanceof Error ? error.message : String(error);
    const errorCode = this.extractErrorCode(error);

    const details = this.extractErrorDetails(error);
    return {
      code: errorCode,
      message: errorMessage,
      ...(details !== undefined && { details }),
      timestamp: new Date(),
      context,
    };
  }

  /**
   * Extract error code from various error types
   */
  protected extractErrorCode(error: unknown): string {
    if (error instanceof Error) {
      // Prisma errors
      if ("code" in error && typeof error.code === "string") {
        return error.code;
      }
      // Custom errors with code property
      if ("name" in error) {
        return error.name;
      }
    }
    return "UNKNOWN_ERROR";
  }

  /**
   * Extract additional error details for logging
   */
  protected extractErrorDetails(error: unknown): Record<string, unknown> | undefined {
    if (error instanceof Error) {
      const details: Record<string, unknown> = {
        name: error.name,
        stack: error.stack,
      };

      // Include additional properties from error object
      for (const [key, value] of Object.entries(error)) {
        if (key !== "message" && key !== "name" && key !== "stack") {
          details[key] = value;
        }
      }

      return details;
    }
    return undefined;
  }

  /**
   * Log successful operation
   */
  protected logOperation(context: ServiceContext, status: string, durationMs: number): void {
    logger.info(
      {
        service: context.serviceName,
        operation: context.operation,
        status,
        durationMs,
        userId: context.userId,
        accountId: context.accountId,
        metadata: context.metadata,
      },
      "Service operation completed"
    );
  }

  /**
   * Log error with context
   */
  protected logError(context: ServiceContext, error: ServiceError, durationMs: number): void {
    logger.error(
      {
        service: context.serviceName,
        operation: context.operation,
        errorCode: error.code,
        errorMessage: error.message,
        errorDetails: error.details,
        durationMs,
        userId: context.userId,
        accountId: context.accountId,
        metadata: context.metadata,
      },
      "Service operation failed"
    );
  }

  /**
   * Log warning
   */
  protected logWarning(context: Omit<ServiceContext, "serviceName">, message: string): void {
    logger.warn(
      {
        service: this.serviceName,
        operation: context.operation,
        userId: context.userId,
        accountId: context.accountId,
        metadata: context.metadata,
      },
      message
    );
  }
}

