const extraModels = {
  project: buildModelMock(createStore(), projectDefaults),
  post: buildModelMock(createStore()),
  postContent: buildModelMock(createStore()),
  channel: buildModelMock(createStore()),
  analytics: buildModelMock(createStore()),
