      const endpoints = [
        "/threads/test-id/performance",
        `/threads/compare?postId=${testProjectId}`,
        `/engagement/trends?projectId=${testProjectId}`,
      ];
      for (const endpoint of endpoints) {
        const response = await app.inject({
          method: "GET",
