      ok: true,
      value: null,
    }));

    const response = await app.inject({
      method: "GET",
      url: "/platforms/unknown/limits",
    });

    expect(response.statusCode).toBe(404);
  });

  it("should get list of supported platforms", async () => {
    const response = await app.inject({
      method: "GET",
