    expect(body.ok).toBe(false);
  });

  // ── POST /content/versions/compare ──────────────────────────────────────

  it("should return 400 for missing version IDs in compare", async () => {
    const res = await app.inject({
      method: "POST",
      url: "/content/versions/compare",
