      apiKey: "test-key",
      model: "llama-3.1-sonar-small-128k-online",
      timeout: 30000,
      retries: 3,
      rateLimit: {
        requestsPerMinute: 60,
        tokensPerMinute: 100000,
        requestsPerDay: 1000,
        tokensPerDay: 1000000,
      },
    };
    const minimalProvider = new PerplexityProvider(minimalConfig);
