    const defaultConsumer = new IntegrationEventConsumer({
      connection: FAKE_CONNECTION,
      handlers: [],
    });
    expect(defaultConsumer.isRunning).toBe(false);

    const customConsumer = new IntegrationEventConsumer({
      connection: FAKE_CONNECTION,
