      { role: "assistant", content: "AI is artificial intelligence" },
      { role: "user", content: "Tell me more" },
    ];

    const generateContentFn = vi.fn(async (params: any) => {
      expect(params.contents.includes("System: You are helpful")).toBeTruthy();
