        {
          id: "page-123",
          messaging: [
            {
              sender: { id: "user-456" },
              recipient: { id: "page-123" },
              timestamp: 1642248000000,
              message: {
                mid: "msg-789",
                text: "Hello via Messenger!",
              },
            },
          ],
        },
      ],
    };

    const result = await processor.parse(payload);

    expect(result.eventType).toBe("COMMENT_RECEIVED");
