                  id: "page-123",
                  name: "Test Page",
                },
                published: true,
              },
            },
          ],
        },
      ],
    };

    const result = await processor.parse(payload);

    expect(result.normalizedData.item).toBe("photo");
    expect(result.normalizedData.link).toBe("https://facebook.com/photo/789");
  });

  it("should parse feed event for video post", async () => {
    const payload = {
      entry: [
        {
          id: "page-123",
          changes: [
            {
              field: "feed",
              value: {
                post_id: "video-999",
                verb: "add",
                item: "video",
                message: "New video posted",
                link: "https://facebook.com/video/999",
                created_time: "2024-01-15T12:00:00Z",
                from: {
                  id: "page-123",
                  name: "Test Page",
                },
                published: true,
              },
            },
          ],
        },
      ],
    };

    const result = await processor.parse(payload);

    expect(result.normalizedData.item).toBe("video");
  });

  it("should parse feed edited event", async () => {
    const payload = {
      entry: [
        {
          id: "page-123",
          changes: [
            {
              field: "feed",
              value: {
                post_id: "post-111",
                verb: "edited",
                item: "status",
                message: "Updated status",
                created_time: "2024-01-15T13:00:00Z",
                from: {
                  id: "page-123",
                  name: "Test Page",
                },
              },
            },
          ],
        },
      ],
    };

    const result = await processor.parse(payload);

    expect(result.normalizedData.verb).toBe("edited");
  });

  it("should parse hidden post event", async () => {
    const payload = {
      entry: [
        {
          id: "page-123",
          changes: [
            {
              field: "feed",
              value: {
                post_id: "post-222",
                verb: "add",
                item: "status",
                message: "Hidden post",
                created_time: "2024-01-15T14:00:00Z",
                from: {
                  id: "page-123",
                  name: "Test Page",
                },
                is_hidden: true,
              },
            },
          ],
        },
      ],
    };

    const result = await processor.parse(payload);

    expect(result.normalizedData.isHidden).toBe(true);
  });

  it("should extract author information from feed event", async () => {
    const payload = {
      entry: [
        {
          id: "page-123",
          changes: [
            {
              field: "feed",
              value: {
                post_id: "post-333",
                verb: "add",
                item: "status",
                message: "Test",
                created_time: "2024-01-15T15:00:00Z",
                from: {
                  id: "user-456",
                  name: "John Doe",
                },
              },
            },
          ],
        },
      ],
    };

    const result = await processor.parse(payload);

    expect(result.normalizedData.from.id).toBe("user-456");
    expect(result.normalizedData.from.name).toBe("John Doe");
  });
});

