  describe("TikTok Adaptation", () => {
    let samplePost: CanonicalPost;

    beforeEach(() => {
      samplePost = {
        id: "test-post-5",
        projectId: "proj-test",
        locale: "en",
        body: "Quick coding tip! \u{1F4A1} #coding #programming #tech",
