  describe("Multi-Provider Adaptation", () => {
    let samplePost: CanonicalPost;

    beforeEach(() => {
      samplePost = {
        id: "test-post-multi",
        projectId: "proj-test",
        locale: "en",
        body: "Universal post for all platforms! \u{1F680}",
        media: [
          {
            id: "media-multi-1",
            url: "https://example.com/image.jpg",
